clear;
clc;

%% 1. Loading in the network
% Default settings struct
settings = struct();

% PowerFlow solver
pfs = PowerFlow("example_network2.txt", settings);

%% 2. Simplifying the network
% Check whether the network is radial
if (pfs.isRadial())
    % If it is radial, simplify it
    fprintf("Network is radial, simplifying...\n");
    pfs.simplifyNetwork();
end

%% 3. Saving the network
% Save the simplified network to a new file
